/**
 * Yearly history behind the "How fast it is growing, and why" section of each /costs page.
 * Generated by apps/website/scripts/gen-cost-trends.py from public data; do not edit by hand.
 *
 * - usdB series: CMS National Health Expenditure Accounts (NHE2024.csv, from 1960, for
 *   spending by service and the net cost of insurance; Tables 5-1 to 5-4 and 5, from 1987,
 *   for who pays).
 * - thousands: BLS Current Employment Statistics, annual average of monthly jobs (via FRED).
 * - index: BLS Employment Cost Index (wages and salaries, from 2001, annual average of
 *   quarters) and CPI-U (annual average of months), via FRED.
 *
 * Each series starts at `firstYear` (its first year with data); `values[i]` is the value
 * for `firstYear + i`.
 */

export const TREND_LAST_YEAR = 2024

export type TrendUnit = "usdB" | "thousands" | "index"

export type TrendSeries = {
  /** Shown above the chart. Null for lines whose label is the cost item's own label. */
  label: string | null
  unit: TrendUnit
  sourceIds: string[]
  firstYear: number
  values: (number | null)[]
}

